WITH exploded AS (SELECT id, latency_ms, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS attr_key, attr_value) SELECT *, PERCENT_RANK() OVER (PARTITION BY attr_key ORDER BY latency_ms DESC) AS latency_ms_percent_rank, SUM(latency_ms) OVER (PARTITION BY attr_key) AS attr_key_sum_latency_ms, SUM(latency_ms) OVER (PARTITION BY attr_key) AS attr_key_sum_latency_ms_2, COUNT(latency_ms) OVER (PARTITION BY attr_key) AS attr_key_count_latency_ms, COUNT(latency_ms) OVER (PARTITION BY attr_key) AS attr_key_count_latency_ms_2 FROM exploded;
